4.1 The estimator, hand-coded and validated

# Design matrix: intercept, launch decay, reset decay, month-end and December indicators
design &lt;- function(dates, lamL = NA, lamR = NA, useL = TRUE, useR = TRUE, useC = TRUE) {
  s &lt;- as.numeric(dates - min(dates)) / 7                              # weeks since the first week
  w &lt;- map_dbl(seq_along(dates), function(i) {                         # weeks since latest reset week
    p &lt;- reset_wk[reset_wk &lt;= dates[i]]
    if (length(p) == 0) NA_real_ else as.numeric(dates[i] - max(p)) / 7
  })
  X &lt;- cbind(`(Intercept)` = rep(1, length(dates)))
  if (useL) X &lt;- cbind(X, launch = exp(-lamL * s))
  if (useR) X &lt;- cbind(X, reset = ifelse(is.na(w), 0, exp(-lamR * w)))
  if (useC) X &lt;- cbind(X, month_end = as.numeric(month(dates) != month(dates + 6)),   # week crosses a month end
                          december  = as.numeric(month(dates) == 12))
  X
}

# Log-likelihood: Poisson (theta = Inf; quasi form for non-integer data) or negative binomial
ll_fun &lt;- function(y, mu, theta) {
  if (is.infinite(theta)) {
    if (all(y == round(y))) sum(dpois(y, mu, log = TRUE)) else sum(y * log(mu) - mu)
  } else sum(dnbinom(y, size = theta, mu = mu, log = TRUE))
}

# IRLS for a log-link GLM with offset; theta = Inf gives Poisson
irls &lt;- function(X, y, off, theta = Inf, tol = 1e-10, maxit = 100) {
  mu &lt;- y + 0.1; eta &lt;- log(mu); ll_old &lt;- -Inf                        # safe starting values
  for (it in seq_len(maxit)) {
    wt   &lt;- if (is.infinite(theta)) mu else mu / (1 + mu / theta)      # working weights
    z    &lt;- eta - off + (y - mu) / mu                                  # working response
    beta &lt;- solve(crossprod(X, wt * X), crossprod(X, wt * z))          # weighted least squares step
    eta  &lt;- off + drop(X %*% beta); mu &lt;- exp(eta)
    ll   &lt;- ll_fun(y, mu, theta)
    if (abs(ll - ll_old) &lt; tol * (abs(ll) + tol)) break                # converged
    ll_old &lt;- ll
  }
  wt &lt;- if (is.infinite(theta)) mu else mu / (1 + mu / theta)
  list(beta = drop(beta), mu = mu, vcov = solve(crossprod(X, wt * X)), loglik = ll, theta = theta)
}

# Negative binomial: alternate IRLS for beta and 1-D maximum likelihood for theta
fit_nb &lt;- function(X, y, off, tol = 1e-8) {
  theta &lt;- 10; ll_old &lt;- -Inf
  for (k in 1:50) {
    f   &lt;- irls(X, y, off, theta)
    opt &lt;- optimize(function(lt) -sum(dnbinom(y, size = exp(lt), mu = f$mu, log = TRUE)),
                    interval = c(-3, 14))                              # search over log(theta)
    theta &lt;- exp(opt$minimum); ll &lt;- -opt$objective
    if (abs(ll - ll_old) &lt; tol) break
    ll_old &lt;- ll
  }
  irls(X, y, off, theta)
}

# Fit one model, profiling the decay rates over a grid
fit_model &lt;- function(y, dates, off, family = c("nb", "pois"), useL = TRUE, useR = TRUE, useC = TRUE,
                      gL = seq(0.02, 0.12, by = 0.01), gR = seq(0.10, 0.60, by = 0.02)) {
  family &lt;- match.arg(family)
  grid &lt;- expand.grid(lamL = if (useL) gL else NA_real_, lamR = if (useR) gR else NA_real_)
  fits &lt;- lapply(seq_len(nrow(grid)), function(i) {
    X &lt;- design(dates, grid$lamL[i], grid$lamR[i], useL, useR, useC)
    f &lt;- if (family == "nb") fit_nb(X, y, off) else irls(X, y, off)
    f$X &lt;- X; f
  })
  grid$ll &lt;- vapply(fits, function(f) f$loglik, numeric(1))
  b &lt;- which.max(grid$ll)
  best &lt;- fits[[b]]
  best$lamL &lt;- grid$lamL[b]; best$lamR &lt;- grid$lamR[b]; best$grid &lt;- grid; best$family &lt;- family
  best$k   &lt;- ncol(best$X) + (family == "nb") + useL + useR            # coefficients + theta + decay rates
  best$aic &lt;- -2 * best$loglik + 2 * best$k
  best
}

# Coefficient table with Wald intervals (phi scales the variance for quasi-Poisson)
coef_tab &lt;- function(f, phi = 1) {
  se &lt;- sqrt(diag(f$vcov) * phi)
  tibble(term = colnames(f$X), est = f$beta, se = se, lo = est - 1.96 * se, hi = est + 1.96 * se)
}
